<script setup>
import ModalContent from './ModalContent.vue'
import HeadlessModal from './HeadlessModal.vue'
import SlideoverContent from './SlideoverContent.vue'
import { onMounted, onUnmounted, ref, computed } from 'vue'
import { lockScroll, markAriaHidden } from '@inertiaui/vanilla'
import { getConfig } from './config'

const modal = ref(null)
const rendered = ref(false)

const emits = defineEmits(['after-leave', 'blur', 'close', 'focus', 'success'])

defineExpose({
    afterLeave: () => modal.value?.afterLeave(),
    close: () => modal.value?.close(),
    emit: (...args) => modal.value?.emit(...args),
    getChildModal: () => modal.value?.getChildModal(),
    getParentModal: () => modal.value?.getParentModal(),
    reload: (...args) => modal.value?.reload(...args),
    setOpen: (...args) => modal.value?.setOpen(...args),

    get config() {
        return modal.value?.config
    },
    get id() {
        return modal.value?.id
    },
    get index() {
        return modal.value?.index
    },
    get isOpen() {
        return modal.value?.isOpen
    },
    get modalContext() {
        return modal.value?.modalContext
    },
    get onTopOfStack() {
        return modal.value?.onTopOfStack
    },
    get shouldRender() {
        return modal.value?.shouldRender
    },
})

// Cleanup functions for scroll lock and aria-hidden
let cleanupScrollLock = null
let cleanupAriaHidden = null

onMounted(() => {
    // Initial setup if modal is already open
    // Only call lockScroll if not already set (onSuccessEvent may have already called it)
    if (modal.value?.isOpen && !cleanupScrollLock) {
        cleanupScrollLock = lockScroll()
        cleanupAriaHidden = markAriaHidden(getConfig('appElement'))
    }
})

onUnmounted(() => {
    cleanupScrollLock?.()
    cleanupAriaHidden?.()
})

// Handle open state changes
function onSuccessEvent() {
    emits('success')
    if (!cleanupScrollLock) {
        cleanupScrollLock = lockScroll()
        cleanupAriaHidden = markAriaHidden(getConfig('appElement'))
    }
}

function onCloseEvent() {
    emits('close')
    cleanupScrollLock?.()
    cleanupAriaHidden?.()
    cleanupScrollLock = null
    cleanupAriaHidden = null
}

const useNativeDialog = computed(() => getConfig('useNativeDialog'))
</script>

<template>
    <HeadlessModal
        ref="modal"
        v-slot="{
            afterLeave,
            close,
            config,
            emit,
            getChildModal,
            getParentModal,
            id,
            index,
            isOpen,
            modalContext,
            onTopOfStack,
            reload,
            setOpen,
            shouldRender,
            ...props
        }"
        @success="onSuccessEvent"
        @close="onCloseEvent"
        @focus="emits('focus')"
        @blur="emits('blur')"
    >
        <Teleport to="body">
            <div
                :data-inertiaui-modal-id="id"
                :data-inertiaui-modal-index="index"
                class="im-dialog relative z-20"
                :aria-hidden="!onTopOfStack"
            >
                <!-- Only render backdrop for the first modal (non-native dialog mode) -->
                <!-- Native dialog uses ::backdrop pseudo-element instead -->
                <Transition
                    v-if="index === 0 && !useNativeDialog"
                    :appear="!rendered"
                    enter-active-class="transition transform ease-in-out duration-300"
                    enter-from-class="opacity-0"
                    enter-to-class="opacity-100"
                    leave-active-class="transition transform ease-in-out duration-300"
                    leave-from-class="opacity-100"
                    leave-to-class="opacity-0"
                    @after-appear="rendered = true"
                >
                    <div
                        v-if="isOpen"
                        class="im-backdrop fixed inset-0 z-30 bg-black/75"
                    />
                </Transition>

                <!-- The modal/slideover content itself -->
                <component
                    :is="config?.slideover ? SlideoverContent : ModalContent"
                    :modal-context="modalContext"
                    :config="config"
                    :use-native-dialog="useNativeDialog"
                    :is-first-modal="index === 0"
                    @after-leave="$emit('after-leave')"
                >
                    <slot
                        v-bind="props"
                        :id="id"
                        :after-leave="afterLeave"
                        :close="close"
                        :config="config"
                        :emit="emit"
                        :get-child-modal="getChildModal"
                        :get-parent-modal="getParentModal"
                        :index="index"
                        :is-open="isOpen"
                        :modal-context="modalContext"
                        :on-top-of-stack="onTopOfStack"
                        :reload="reload"
                        :set-open="setOpen"
                        :should-render="shouldRender"
                    />
                </component>
            </div>
        </Teleport>
    </HeadlessModal>
</template>
